          console.error('   🔎 Self-probe skipped — set PUBLIC_URL in .env to your tunnel URL');
          console.error('       (e.g. PUBLIC_URL=https://mentrayolo.share.zrok.io) to enable it.');
        }
      }

      if (err.stack) {
        console.error(`   Stack: ${err.stack}`);
      }
      console.error('');
