        ? "Photo request timed out (30s). The cloud could not deliver the photo to this AppServer — check your public tunnel + console.mentra.glass Public URL."
        : err?.message || String(err);
      throw new Error(probeSummary ? `${baseMsg} Self-probe: ${probeSummary}` : baseMsg);
    }

    const stored: StoredPhoto = {
      requestId: photo.requestId,
